const fs = require('node:fs');
const { checkSettings } = require('./validate.js');
function loadSettings(file) {
  const cfg = JSON.parse(fs.readFileSync(file, 'utf8'));
  return checkSettings(cfg);
}
module.exports = { loadSettings };

